import React, { useState, useEffect } from 'react';
import {
  Box,
  Card,
  Grid,
  Tab,
  Tabs,
  Typography,
  Button,
  IconButton,
} from '@mui/material';
import MDBox from 'components/MDBox';
import MDTypography from 'components/MDTypography';
import CloseIcon from '@mui/icons-material/Close';
import AddIcon from '@mui/icons-material/Add';
import FrontendLayout from "layouts/frontend";
import axios from 'axios';
import DashboardSidebar from './DashboardSidebar';

const MyCards = () => {
  const [userInfo, setUserInfo] = useState(null);
  const [loading, setLoading] = useState(true);
  const [selectedTab, setSelectedTab] = useState(0);

  const cardData = [
    {
      type: 'visa',
      number: 'XXXX XXXX XXXX 4242',
      expiry: '04/25',
      status: 'Active'
    }
  ];

  useEffect(() => {
    const fetchUserInfo = async () => {
      try {
        const token = localStorage.getItem('token');
        const response = await axios.get(`${process.env.REACT_APP_API_URL}/me`, {
          headers: {
            Authorization: `Bearer ${token}`
          }
        });
        setUserInfo(response.data.data.userInfo);
      } catch (error) {
        console.error('Error fetching user info:', error);
      } finally {
        setLoading(false);
      }
    };

    fetchUserInfo();
  }, []);

  const handleTabChange = (event, newValue) => {
    setSelectedTab(newValue);
  };

  const TabPanel = ({ children, value, index }) => {
    return (
      <div role="tabpanel" hidden={value !== index}>
        {value === index && (
          <Box sx={{ py: 2 }}>
            {children}
          </Box>
        )}
      </div>
    );
  };

  if (loading) {
    return (
      <FrontendLayout>
        <MDBox>
          <Typography>Loading...</Typography>
        </MDBox>
      </FrontendLayout>
    );
  }

  return (
    <FrontendLayout>
      <MDBox>
        <Grid container spacing={3}>
          {/* Left Sidebar */}
          <Grid item xs={12} md={3}>
            <DashboardSidebar userInfo={userInfo} />
          </Grid>

          {/* Main Content Area */}
          <Grid item xs={12} md={9}>
            <Card sx={{ p: 3, backgroundColor: 'white' }}>
              <MDTypography variant="h5" color="dark" mb={3}>
                Payment Cards
              </MDTypography>

              <Box sx={{ borderBottom: 1, borderColor: 'divider', mb: 3 }}>
                <Tabs
                  value={selectedTab}
                  onChange={handleTabChange}
                  sx={{
                    '& .MuiTab-root': {
                      textTransform: 'none',
                      fontSize: '1rem',
                      fontWeight: 500,
                      minWidth: 120,
                      color: '#666',
                      px: 3,
                    },
                    '& .Mui-selected': {
                      color: '#213a93 !important',
                    },
                    '& .MuiTabs-indicator': {
                      backgroundColor: '#213a93',
                      height: '3px',
                    },
                  }}
                >
                  <Tab label="Your Cards" />
                  <Tab label="Payments" />
                </Tabs>
              </Box>

              <TabPanel value={selectedTab} index={0}>
                <Box sx={{ display: 'flex', justifyContent: 'flex-end', mb: 2 }}>
                  <Button
                    variant="contained"
                    startIcon={<AddIcon />}
                    sx={{
                      backgroundColor: '#213a93',
                      '&:hover': { backgroundColor: '#1a2d75' }
                    }}
                  >
                    Add Card
                  </Button>
                </Box>

                <Grid container spacing={2}>
                  <Grid item xs={12}>
                    <Box sx={{ width: '100%', overflow: 'auto' }}>
                      <Box sx={{ minWidth: 650 }}>
                        <Box sx={{ mb: 2, fontWeight: 'bold' }}>
                          <Grid container>
                            <Grid item xs={3}>Card Number</Grid>
                            <Grid item xs={3}>Expiration Date</Grid>
                            <Grid item xs={3}>Status</Grid>
                            <Grid item xs={3}>Action</Grid>
                          </Grid>
                        </Box>

                        {cardData.map((card, index) => (
                          <Box
                            key={index}
                            sx={{
                              py: 2,
                              borderBottom: '1px solid #eee',
                              '&:last-child': { borderBottom: 'none' }
                            }}
                          >
                            <Grid container alignItems="center">
                              <Grid item xs={3}>
                                <Box sx={{ display: 'flex', alignItems: 'center' }}>
                                  <Box
                                    component="img"
                                    src="/visa-logo.png"
                                    alt="Visa"
                                    sx={{ width: 40, mr: 2 }}
                                  />
                                  {card.number}
                                </Box>
                              </Grid>
                              <Grid item xs={3}>{card.expiry}</Grid>
                              <Grid item xs={3}>
                                <Box
                                  sx={{
                                    display: 'inline-block',
                                    px: 2,
                                    py: 0.5,
                                    borderRadius: '16px',
                                    backgroundColor: '#e8f5e9',
                                    color: '#2e7d32'
                                  }}
                                >
                                  {card.status}
                                </Box>
                              </Grid>
                              <Grid item xs={3}>
                                <IconButton
                                  size="small"
                                  sx={{
                                    color: '#f44336',
                                    '&:hover': { backgroundColor: '#ffebee' }
                                  }}
                                >
                                  <CloseIcon />
                                </IconButton>
                              </Grid>
                            </Grid>
                          </Box>
                        ))}
                      </Box>
                    </Box>
                  </Grid>
                </Grid>

                <Box sx={{ mt: 4, p: 2, backgroundColor: '#fff3e0', borderRadius: 1 }}>
                  <Typography variant="body2" color="textSecondary">
                    <span role="img" aria-label="info">ℹ️</span> The charges on your credit card statement will appear as Loghic research.
                  </Typography>
                </Box>

                <Box sx={{ mt: 3 }}>
                  <Typography variant="body2" color="textSecondary">
                    We are fully compliant with Payment Card Industry Data Security Standards.
                  </Typography>
                  <Box sx={{ mt: 2, display: 'flex', gap: 2 }}>
                    <Box component="img" src="/visa-logo.png" alt="Visa" sx={{ height: 20 }} />
                    <Box component="img" src="/mastercard-logo.png" alt="Mastercard" sx={{ height: 20 }} />
                    <Box component="img" src="/amex-logo.png" alt="American Express" sx={{ height: 20 }} />
                    <Box component="img" src="/discover-logo.png" alt="Discover" sx={{ height: 20 }} />
                    <Box component="img" src="/jcb-logo.png" alt="JCB" sx={{ height: 20 }} />
                  </Box>
                </Box>
              </TabPanel>

              <TabPanel value={selectedTab} index={1}>
                <Typography>Payment history will be displayed here</Typography>
              </TabPanel>
            </Card>
          </Grid>
        </Grid>
      </MDBox>
    </FrontendLayout>
  );
};

export default MyCards; 